import { BACKEND_ATLAS } from '../../generated/backend-atlas.12e71c84ee5d.mjs';
import { icon } from '../../core/icon.c3afdb20bfa7.mjs';
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function buildCapabilitiesViewModel({query='',domain=null,method='all'}={}){const q=String(query).trim().toLowerCase();const entries=BACKEND_ATLAS.entries.filter(x=>(!domain||x.domain===domain)&&(method==='all'||x.method===method)&&(!q||`${x.method} ${x.path} ${x.domain} ${x.kind}`.toLowerCase().includes(q)));return Object.freeze({atlas:BACKEND_ATLAS,query,domain,method,entries:Object.freeze(entries)});}
export function renderCapabilitiesView(model=buildCapabilitiesViewModel()){const a=model.atlas;const read=a.entries.filter(x=>x.method==='GET').length;const write=a.total-read;return `<section class="capability-atlas"><header class="capability-atlas__hero"><div><p class="eyebrow">Backend truth map</p><h1>Capability Atlas</h1><p>Every route discovered from <code>${esc(a.source)}</code>. Nothing is invented, and write-capable surfaces remain clearly marked.</p></div><div class="atlas-receipt"><span>Source receipt</span><code>${esc(a.sourceSha256.slice(0,18))}…</code></div></header><div class="atlas-metrics"><span><strong>${a.total}</strong><small>routes and patterns</small></span><span><strong>${a.domains.length}</strong><small>backend domains</small></span><span><strong>${read}</strong><small>read surfaces</small></span><span><strong>${write}</strong><small>state-changing surfaces</small></span></div><div class="atlas-layout"><aside class="atlas-domains"><header><strong>Domains</strong><span>${a.domains.length}</span></header><label>${icon('search',{size:14})}<input type="search" data-atlas-search placeholder="Filter routes" value="${esc(model.query)}"></label><div><button data-atlas-domain="" aria-pressed="${!model.domain}"><span>All domains</span><strong>${a.total}</strong></button>${a.domains.map(d=>`<button data-atlas-domain="${esc(d.id)}" aria-pressed="${model.domain===d.id}"><span>${esc(d.id)}</span><strong>${d.count}</strong></button>`).join('')}</div></aside><main class="atlas-routes"><header><div><strong>${model.domain?esc(model.domain):'All backend routes'}</strong><span>${model.entries.length} visible</span></div><div class="segmented-control">${['all','GET','POST','PUT','DELETE'].map(m=>`<button data-atlas-method="${m}" aria-pressed="${model.method===m}">${m}</button>`).join('')}</div></header><div class="atlas-table"><div class="atlas-table__head"><span>Method</span><span>Route</span><span>Domain</span><span>Kind</span><span>Source</span></div>${model.entries.map(e=>`<article><span class="method-badge" data-method="${esc(e.method)}">${esc(e.method)}</span><code>${esc(e.path)}</code><span>${esc(e.domain)}</span><span>${esc(e.kind)}</span><a href="../src/server/routes.mjs#L${e.line}" title="Source line">L${e.line}</a></article>`).join('')}</div></main></div></section>`}
